const SEASONS=['inverno','primavera','estate','autunno'],IRON_MIN=8,BASIC=['olio extravergine'];
const r1=x=>Math.round(x*10)/10;
function grams(x){return x.unit==='pz'?Number(x.qty)*(PZ[x.name]||100):Number(x.qty)}
function compute(ings){const t=[0,0,0,0,0,0];for(const x of ings||[]){const n=N[String(x.name).toLowerCase()];if(!n)continue;const g=grams(x)/100;for(let i=0;i<6;i++)t[i]+=n[i]*g}return{kcal:Math.round(t[0]),prot:r1(t[1]),carb:r1(t[2]),fat:r1(t[3]),fib:r1(t[4]),iron:r1(t[5])}}
function scale(recipe,f){if(Math.abs(f-1)<.005)return{...recipe,scale:1};const ings=(recipe.ingredients||[]).map(x=>{if(x.unit==='pz')return{...x,qty:Math.max(1,Math.round(x.qty*f))};const step=x.qty<20?1:5;return{...x,qty:Math.max(step,Math.round(x.qty*f/step)*step)}});const nutrition=compute(ings);return{...recipe,ingredients:ings,nutrition,kcal:nutrition.kcal,carboidrati:nutrition.carb,proteine:nutrition.prot,grassi:nutrition.fat,fibre:nutrition.fib,ricco_di_ferro:nutrition.iron>=IRON_MIN?'si':'no',ferro:nutrition.iron>=IRON_MIN?'si':'no',scale:Math.round(f*100)/100}}
const out=[];let row=0;
B.forEach((b,bi)=>{for(const s of (b.se||SEASONS)){let prods;
 if(!b.p)prods=[null];else if(b.p==='pool'){const pool=POOL[s].filter(v=>!b.i.some(x=>x[0]===v));prods=[];for(let j=0;j<4&&j<pool.length;j++)prods.push(pool[(bi*3+j)%pool.length])}else prods=b.p[s]||[];
 for(const p of prods){const ings=b.i.map(x=>({name:x[0],qty:x[1],unit:x[2]||'g'}));
  if(p&&!ings.some(x=>x.name===p)){const it={name:p,qty:b.q,unit:'g'};if(b.pi!==undefined)ings.splice(b.pi,0,it);else{const oi=ings.findIndex(x=>x.name==='olio extravergine');oi>=0?ings.splice(oi,0,it):ings.push(it)}}
  /* Colonne del database: [kcal, carboidrati, proteine, grassi, fibre, ferro mg, ricco di ferro 1/0] */
  const C=COLS&&COLS[row++];const nutrition=C?{kcal:C[0],carb:C[1],prot:C[2],fat:C[3],fib:C[4],iron:C[5]}:compute(ings);const ferro=C?(C[6]?'si':'no'):(nutrition.iron>=IRON_MIN?'si':'no');
  const tags=[...new Set([...(b.tg||[]),...(p&&PTAG[p]||[]),...(ferro==='si'?['ricco di ferro']:[])])];
  out.push({id:b.k+'-'+s+'-'+(p||'base'),slot:b.s,season:s,produce:p||'',title:p?`${b.t} · ${p} (${s})`:`${b.t} (${s})`,origin:b.o||'',ingredients:ings,steps:String(b.st).split('{p}').join(p||'verdure di stagione'),tags,sauceTip:b.sc||'',market:!!b.m,kcal:nutrition.kcal,carboidrati:nutrition.carb,proteine:nutrition.prot,grassi:nutrition.fat,fibre:nutrition.fib,ricco_di_ferro:ferro,nutrition,ferro});}}});
window.BSP_RECIPE_CATALOG=out;
window.BSPnutri={table:N,pz:PZ,basic:BASIC,compute,scale,ironMin:IRON_MIN,byTitle:t=>out.find(r=>r.title===t)};

